INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('004afa2a-d390-4faa-bbbb-770dff01f616', 'c3c3c3c3-3030-4000-8000-000000000003', 9, 'Dia 9 — Simplicidade', 'Semana 2: Organizar', '{"pch": "Se n\u00e3o vos converterdes como crian\u00e7as\u2026 A crian\u00e7a n\u00e3o complica. Ela vive.", "verse": "Mt 18,3", "lectio": "Leia Mt 18,1-5. Tornar-se como crian\u00e7a.", "practice": "Simplifique 1 \u00e1rea da sua vida hoje. Menos \u00e9 clareza.", "question": "O que voc\u00ea est\u00e1 complicando desnecessariamente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;